const loader=new GLTFLoader(),textures=new THREE.TextureLoader();
function configure(root){root.traverse(o=>{if(!o.isMesh)return;o.castShadow=true;o.receiveShadow=true;if(o.isSkinnedMesh)o.frustumCulled=false;for(const m of Array.isArray(o.material)?o.material:[o.material]){m.roughness=1;m.metalness=0;if(/leafsGreen|grass/i.test(m.name))m.color.set('#71834c');if(/woodBark/i.test(m.name))m.color.set('#716046');}});return root;}
function normalize(root,height){root.updateMatrixWorld(true);const bounds=new THREE.Box3().setFromObject(root);const size=bounds.getSize(new THREE.Vector3());const s=height/size.y;const wrapper=new THREE.Group();root.scale.multiplyScalar(s);root.position.y-=bounds.min.y*s;wrapper.add(root);return wrapper;}
function loaded(url){return loader.loadAsync(url).then(g=>{configure(g.scene);return g;});}
function texture(url,repeat=1){return textures.loadAsync(url).then(t=>{t.colorSpace=THREE.SRGBColorSpace;t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(repeat,repeat);t.anisotropy=8;return t;});}
export async function upgradeWorld({scene,ground,trees,actors,software,onStatus}){
 const status=onStatus??(()=>{});let ready=0;const total=13;const load=async(url)=>{const result=await loaded(url);status(++ready,total);return result;};
 const files={oak:'nature/tree_oak.glb',pine:'nature/tree_pineTallA_detailed.glb',tree:'nature/tree_detailed.glb',bush:'nature/plant_bushDetailed.glb',grass:'nature/grass_large.glb',leaves:'nature/grass_leafsLarge.glb',farmer:'farmer.glb',adventurer:'adventurer.glb',fern:'scanned/fern/model.gltf',cliff:'nature/rock_largeA.glb',reed:'nature/plant_flatTall.glb',bridge:'nature/bridge_wood.glb',sword:'weapons/sword_1handed.gltf'};
 const entries=await Promise.allSettled(Object.entries(files).map(async([key,url])=>[key,await load('assets/'+url)]));const models={};const failed=[];for(let i=0;i<entries.length;i++){let r=entries[i];if(r.status==='fulfilled')models[r.value[0]]=r.value[1];else{failed.push(Object.keys(files)[i]);console.error('Asset failed',Object.keys(files)[i],r.reason);}}
 const meshInfo=await fetch('assets/scanned/boulder/mesh.json').then(r=>r.json());const lod=meshInfo.variants[0].low;const [vb,ib,rockMap]=await Promise.all([fetch('assets/scanned/boulder/'+lod.vertices).then(r=>r.arrayBuffer()),fetch('assets/scanned/boulder/'+lod.indices).then(r=>r.arrayBuffer()),texture('assets/scanned/boulder/textures/boulder_01_diff_1k.jpg')]);const floats=new Float32Array(vb),inter=new THREE.InterleavedBuffer(floats,8),geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.InterleavedBufferAttribute(inter,3,0));geo.setAttribute('normal',new THREE.InterleavedBufferAttribute(inter,3,3));geo.setAttribute('uv',new THREE.InterleavedBufferAttribute(inter,2,6));geo.setIndex(new THREE.BufferAttribute(new Uint32Array(ib),1));models.rock={scene:new THREE.Mesh(geo,new THREE.MeshStandardMaterial({map:rockMap,roughness:1}))};
 const bark=await texture('assets/textured-trees/Tree_Bark.jpg'),leaves=await texture('assets/textured-trees/Tree_Leaves.png'),birchBark=await texture('assets/textured-trees/Birch_Bark.png'),birchLeaves=await texture('assets/textured-trees/Birch_Leaves_Green.png'),pineLeaves=await texture('assets/textured-trees/Pine_Leaves.png');
 const objLoader=new OBJLoader();for(const [key,name] of [['tree','Tree_1'],['oak','Tree_4'],['birch','Birch_3'],['pine','Pine_2']]){const root=await objLoader.loadAsync('assets/textured-trees/'+name+'.obj');root.traverse(o=>{if(!o.isMesh)return;const make=old=>{const isLeaf=/Leaves/i.test(old.name),map=/Birch_Bark/i.test(old.name)?birchBark:isLeaf?(key==='birch'?birchLeaves:key==='pine'?pineLeaves:leaves):bark;return new THREE.MeshStandardMaterial({map,roughness:1,alphaTest:isLeaf?.45:0,side:THREE.DoubleSide});};o.material=Array.isArray(o.material)?o.material.map(make):make(o.material);o.castShadow=true;o.receiveShadow=true;});models[key]={scene:root};}
 const dirt=await texture('assets/scanned/ground/diffuse.jpg',32);ground.material=new THREE.MeshStandardMaterial({map:dirt,color:'#b4b5a0',roughness:1});
 const rough=await textures.loadAsync('assets/scanned/ground/rough.jpg');rough.wrapS=rough.wrapT=THREE.RepeatWrapping;rough.repeat.set(32,32);ground.material.roughnessMap=rough;
 const [wallMap,woodMap,grassMap]=await Promise.all([texture('assets/scanned/concrete_wall_006_diffuse.jpg',2),texture('assets/scanned/wood_planks_grey_diffuse.jpg'),texture('assets/scanned/aerial_grass_rock_diffuse.jpg',42)]);scene.traverse(o=>{if(!o.isMesh||Array.isArray(o.material))return;const hex=o.material.color?.getHexString();if(['9b8763','655b46','797c66'].includes(hex)){o.material=new THREE.MeshStandardMaterial({map:wallMap,color:hex==='9b8763'?'#d4bb92':'#9e9d8b',roughness:1});}else if(['483e2c','6b5c42','675b40'].includes(hex)){o.material=new THREE.MeshStandardMaterial({map:woodMap,color:'#aa9676',roughness:1});}else if(hex==='a79970'){const map=dirt.clone();map.repeat.set(1,1);o.material=new THREE.MeshStandardMaterial({map,color:'#c7bb96',roughness:1});}});
 const yard=new THREE.Mesh(new THREE.CircleGeometry(36,48),ground.material);yard.rotation.x=-Math.PI/2;yard.position.set(0,.012,0);yard.material=ground.material.clone();yard.material.map=dirt.clone();yard.material.map.repeat.set(8,8);yard.receiveShadow=true;scene.add(yard);ground.material=new THREE.MeshStandardMaterial({map:grassMap,color:'#aab18d',roughness:1});
 const parts=[];function place(key,x,z,height,rotation=0){if(!models[key])return;let source=models[key].scene;if(key==='fern'){source=source.children.find(o=>o.isMesh)||source;}const root=normalize(source.clone(true),height);root.position.set(x,0,z);root.rotation.y=rotation;root.traverse(o=>{o.userData.maxDistance=key==='grass'||key==='leaves'?35:key==='fern'||key==='rock'?25:200;});scene.add(root);parts.push(root);return root;}
 for(const [x,z,s] of [[-24,20,1],[22,24,1],[-24,-26,1.2],[26,-20,1.1],[-9,31,.9],[24,4,1]])trees.push({x,z,s});
 for(let i=0;i<trees.length;i++){const p=trees[i];place(i%4===0?'pine':i%4===1?'oak':i%4===2?'birch':'tree',p.x,p.z,p.s*(i%3===0?12:9),i*2.4);}
 let seed=9841;const rand=()=>{seed=seed*16807%2147483647;return(seed-1)/2147483646;};
 for(let i=0;i<180;i++){const x=rand()*150-75,z=rand()*155-65;if(Math.abs(x)<4|| (Math.abs(x)<24&&z>-28&&z<20)||(x>24&&x<58&&z>1&&z<46))continue;place(i%5===0?'bush':i%2?'grass':'leaves',x,z,i%5===0?1.4+rand():.35+rand()*.65,rand()*6.28);}
 // Scanned rocks and ferns replace the geometric arena stones and vegetation.
 for(let i=0;i<12;i++){let a=i*2.4,x=Math.sin(a)*(30+rand()*40),z=Math.cos(a)*(32+rand()*45);place('rock',x,z,.7+rand()*2.3,a);if(i<8)place('fern',x+2,z+2,.6+rand()*.9,a);}
 for(let i=0;i<14;i++){const a=i/14*Math.PI*2;place('cliff',Math.sin(a)*153,Math.cos(a)*153,35+rand()*55,a);}
 for(let row=0;row<3;row++)for(let col=0;col<2;col++)for(let a=0;a<5;a++)for(let b=0;b<4;b++)place('reed',24+col*16+a*2.8,3+row*14+b*3,.65+rand()*.35,rand()*6.28);
 const animated=[];
 for(let i=0;i<actors.length;i++){const actor=actors[i],key=i===1?'farmer':'adventurer',model=models[key];if(!model)continue;if(software&&!model.cpuPrepared){model.scene.traverse(o=>{if(o.isSkinnedMesh)o.geometry=characterLOD(o.geometry);});model.cpuPrepared=true;}const root=clone(model.scene);root.traverse(o=>{if(o.name==='Backpack')o.visible=false;if(o.isMesh){o.userData.maxDistance=45;o.frustumCulled=!o.isSkinnedMesh;o.material=Array.isArray(o.material)?o.material.map(m=>m.clone()):o.material.clone();const materials=Array.isArray(o.material)?o.material:[o.material];for(let m of materials){if(/green|lightgreen|lightblue/i.test(m.name))m.color.set(i===0?'#6c715b':i===1?'#7b7561':['#554b39','#4c6145','#4f5b67'][i-2]);}}});const wrapped=normalize(root,2.25);actor.g.add(wrapped);actor.visual=wrapped;if(i!==1&&models.sword){actor.g.updateMatrixWorld(true);const hand=(root.getObjectByName('Wrist.R')||root.getObjectByName('WristR'));if(hand){const blade=normalize(models.sword.scene.clone(true),.95*actor.g.scale.x),handScale=hand.getWorldScale(new THREE.Vector3());blade.scale.set(1/handScale.x,1/handScale.y,1/handScale.z);blade.rotation.x=Math.PI;hand.add(blade);}}const mixer=new THREE.AnimationMixer(root);const actions={};for(let clip of model.animations){const name=clip.name.split('|').pop();actions[name]=mixer.clipAction(clip);}const entry={actor,mixer,actions,current:null,attackTimer:0};animated.push(entry);setAction(entry,'Idle_Neutral');
 }
 function setAction(entry,name){const next=entry.actions[name]??entry.actions.Idle_Neutral??entry.actions.Idle;if(!next||entry.current===next)return;entry.current?.fadeOut(.15);next.reset().fadeIn(.15).play();entry.current=next;}
 for(const [x,z] of [[-6,16],[7,23],[-8,-3],[19,-19],[23,12],[-21,21]])place('fern',x,z,.8,0);
 status(total,total);return {failed,animated,update(dt,{moving,running,attacking,dodging,time}){for(let i=0;i<animated.length;i++){const e=animated[i],a=e.actor;if(!a.g.visible)continue;let action='Idle_Neutral';if(i===0)action=dodging?'Roll':attacking?'Sword_Slash':moving?running?'Run':'Walk':'Idle_Neutral';else if(a.state==='chase')action='Walk';else if(a.state==='windup')action='Idle_Sword';else if(a.state==='recover')action='Sword_Slash';setAction(e,action);e.mixer.update(dt);}}};
}
